//! fast hashing and comparison.
//!
//! An [`Atom`] is created by interning a string in an [`AtomStore`]. Interning
//! the same string content more than once in a single store yields atoms that
//! share the same backing allocation, which makes cloning cheap and equality
//! checks fast. Atoms are reference counted, so they remain valid even after the
//! [`AtomStore`] that created them has been dropped.

use std::{
    borrow::Cow,
    collections::{hash_map::DefaultHasher, HashMap},
    fmt,
    hash::{Hash, Hasher},
    ptr::NonNull,
    sync::atomic::{fence, AtomicUsize, Ordering},
};

#[cfg(test)]
mod tests;

/// The heap allocated, reference counted backing storage of an [`Atom`].
struct Entry {
    /// Number of live [`Atom`]s pointing at this entry.
    ref_count: AtomicUsize,
    /// Precomputed hash of `string`. It is computed with a fixed seed so that
    /// the same string always hashes to the same value, regardless of the
    /// [`AtomStore`] that created the atom.
    hash: u64,
    /// The interned string data.
    string: Box<str>,
}

/// An immutable, interned string optimized for fast hashing and comparison.
///
/// Atoms are cheap to clone and compare. Two atoms that represent the same
/// string content are always equal, even when they originate from different
/// [`AtomStore`]s.
pub struct Atom {
    /// A pointer to the reference counted [`Entry`] backing this atom.
    ///
    /// This is named `unsafe_data` because dereferencing it relies on the
    /// reference counting invariants maintained by [`Clone`] and [`Drop`].
    unsafe_data: NonNull<Entry>,
}

// The backing `Entry` is reference counted atomically, so `Atom` can be shared
// across threads just like `Arc<str>`.
unsafe impl Send for Atom {}
unsafe impl Sync for Atom {}

impl Atom {
    /// Allocates a fresh, reference counted entry for `text` and returns an atom
    /// pointing at it.
    fn new(text: &str) -> Self {
        let entry = Box::new(Entry {
            ref_count: AtomicUsize::new(1),
            hash: compute_hash(text),
            string: text.into(),
        });

        Atom {
            // `Box::into_raw` never returns a null pointer.
            unsafe_data: unsafe { NonNull::new_unchecked(Box::into_raw(entry)) },
        }
    }

    #[inline]
    fn entry(&self) -> &Entry {
        // Safety: the entry is kept alive for as long as this atom exists.
        unsafe { self.unsafe_data.as_ref() }
    }

    /// Returns the string content of this atom.
    #[inline]
    pub fn as_str(&self) -> &str {
        &self.entry().string
    }

    /// Returns a hash of the string content.
    ///
    /// The hash is derived from the string content with a fixed seed, so atoms
    /// representing the same string return the same hash regardless of which
    /// [`AtomStore`] created them.
    #[inline]
    fn get_hash(&self) -> u64 {
        self.entry().hash
    }
}

impl Clone for Atom {
    fn clone(&self) -> Self {
        // A relaxed increment is sufficient: holding a reference already
        // guarantees the entry stays alive, mirroring `Arc::clone`.
        self.entry().ref_count.fetch_add(1, Ordering::Relaxed);

        Atom {
            unsafe_data: self.unsafe_data,
        }
    }
}

impl Drop for Atom {
    fn drop(&mut self) {
        if self.entry().ref_count.fetch_sub(1, Ordering::Release) != 1 {
            return;
        }

        // This was the last reference, so free the backing entry. The acquire
        // fence synchronizes with the release above, mirroring `Arc`.
        fence(Ordering::Acquire);
        unsafe {
            drop(Box::from_raw(self.unsafe_data.as_ptr()));
        }
    }
}

impl PartialEq for Atom {
    fn eq(&self, other: &Self) -> bool {
        // Same allocation is trivially equal.
        if self.unsafe_data == other.unsafe_data {
            return true;
        }

        // Otherwise compare content, using the precomputed hash as a fast
        // rejection check. This makes atoms from different stores compare equal
        // when they represent the same string.
        self.get_hash() == other.get_hash() && self.as_str() == other.as_str()
    }
}

impl Eq for Atom {}

impl Hash for Atom {
    fn hash<H: Hasher>(&self, state: &mut H) {
        state.write_u64(self.get_hash());
    }
}

impl fmt::Debug for Atom {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        fmt::Debug::fmt(self.as_str(), f)
    }
}

impl fmt::Display for Atom {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        fmt::Display::fmt(self.as_str(), f)
    }
}

/// A store that interns strings into [`Atom`]s.
///
/// Interning the same string content twice in the same store yields atoms that
/// share the same backing allocation. Different stores maintain independent
/// allocations, so atoms interned from distinct stores never share storage even
/// when they represent the same string.
#[derive(Default)]
pub struct AtomStore {
    /// Maps interned string content to a canonical atom for this store.
    data: HashMap<Box<str>, Atom>,
}

impl AtomStore {
    /// Interns `text` into this store and returns the corresponding [`Atom`].
    ///
    /// Calling this method with equal string content on the same store returns
    /// atoms backed by the same allocation.
    pub fn atom<'a>(&mut self, text: impl Into<Cow<'a, str>>) -> Atom {
        let text = text.into();

        if let Some(existing) = self.data.get(text.as_ref()) {
            return existing.clone();
        }

        let atom = Atom::new(&text);
        self.data
            .insert(text.into_owned().into_boxed_str(), atom.clone());
        atom
    }
}

/// Computes a deterministic hash of `text` using a fixed seed.
fn compute_hash(text: &str) -> u64 {
    let mut hasher = DefaultHasher::new();
    text.hash(&mut hasher);
    hasher.finish()
}
