[metadata] {"type": "create", "filePath": "/workspace/repo/crates/hstr/src/tests.rs", "content": "use crate::{Atom, AtomStore};

#[test]
fn same_store_same_content_shares_data() {
    let mut store = AtomStore::default();

    let a = store.atom("hello");
    let b = store.atom("hello");

    assert_eq!(a.unsafe_data, b.unsafe_data);
    assert_eq!(a, b);
}

#[test]
fn different_stores_same_content_have_different_data() {
    let mut store1 = AtomStore::default();
    let mut store2 = AtomStore::default();

    let a = store1.atom("hello");
    let b = store2.atom("hello");

    assert_ne!(a.unsafe_data, b.unsafe_data);
}

#[test]
fn different_stores_same_content_are_equal() {
    let mut store1 = AtomStore::default();
    let mut store2 = AtomStore::default();

    let a = store1.atom("hello");
    let b = store2.atom("hello");

    assert_eq!(a, b);
}

#[test]
fn different_content_is_not_equal() {
    let mut store = AtomStore::default();

    let a = store.atom("hello");
    let b = store.atom("world");

    assert_ne!(a, b);
    assert_ne!(a.unsafe_data, b.unsafe_data);
}

#[test]
fn hash_is_consistent_across_stores() {
    let mut store1 = AtomStore::default();
    let mut store2 = AtomStore::default();

    let a = store1.atom("hello");
    let b = store2.atom("hello");

    assert_eq!(a.get_hash(), b.get_hash());
}

#[test]
fn atom_outlives_store() {
    let atom = {
        let mut store = AtomStore::default();
        store.atom("persisted")
    };

    // The store has been dropped, but the atom is still usable.
    let cloned = atom.clone();
    assert_eq!(atom, cloned);
    assert_eq!(atom.as_str(), "persisted");
}

#[test]
fn accepts_owned_and_borrowed() {
    let mut store = AtomStore::default();

    let borrowed = store.atom("shared");
    let owned = store.atom(String::from("shared"));

    assert_eq!(borrowed.unsafe_data, owned.unsafe_data);
    assert_eq!(borrowed, owned);
}
